WITH with_windows AS (SELECT id, started_at, country, LAST_VALUE(browser) IGNORE NULLS OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser FROM sessions WHERE customer_id IN (19, 28)), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC NULLS FIRST, id) AS dedup_rank FROM with_windows) x WHERE dedup_rank = 1), metrics AS (SELECT id, last_known_browser, dedup_rank, ROW_NUMBER() OVER (ORDER BY dedup_rank, id) AS seq_no, FIRST_VALUE(country, TRUE) OVER (PARTITION BY country ORDER BY dedup_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country FROM latest), latest_match AS (SELECT s.id, s.dedup_rank, s.first_known_country, latest.page, latest.web_event_event_type FROM metrics s LEFT JOIN LATERAL (SELECT c.page, c.event_type AS web_event_event_type FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT page, COUNT(CASE WHEN web_event_event_type = 'page_view' THEN 1 END) AS page_view_count, COUNT(DISTINCT web_event_event_type) AS distinct_web_event_event_types, SIZE(COLLECT_SET(web_event_event_type)) AS num_web_event_event_types FROM latest_match GROUP BY 1 HAVING distinct_web_event_event_types < 1000;
